head.script:
scwin.screenId = "jldinf00003";

///////// 1. 변수 및 선언 영역 /////////

scwin.emb1 = $c.util.getComponent('emb1');

scwin.emb2 = $c.util.getComponent('emb2');

scwin.emb3 = $c.util.getComponent('emb3');


///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf00003.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_viewMv_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_viewMv_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_viewMv_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.viewMv(1)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00003.btn_viewMv_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_viewMv_2_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_viewMv_2_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_viewMv_2_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.viewMv(2)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00003.btn_viewMv_2_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_viewMv_3_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_viewMv_3_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_viewMv_3_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.viewMv(3)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00003.btn_viewMv_3_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.viewMv
 * @author Inswave
 * @date 2026. 09. 29
 * @param gubun
 * @returns
 * @hidden N
*/
scwin.viewMv = function (gubun) {
    /* sdd-asis-lifecycle:begin viewMv — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#movie" + gubun).attr("style", "display:;");
    scwin.emb1.setStyle("display", "none");
    scwin.emb2.setStyle("display", "none");
    scwin.emb3.setStyle("display", "none");
    if (gubun === "1") {
        $c.util.getComponent("movie2").setStyle("display", "none");
        $c.util.getComponent("movie3").setStyle("display", "none");
        self.setTimeout(function(){ scwin.playMovie('emb1') }, 1000);
    } else {
        if (gubun === "2") {
            $c.util.getComponent("movie1").setStyle("display", "none");
            $c.util.getComponent("movie3").setStyle("display", "none");
            self.setTimeout(function(){ scwin.playMovie('emb2') }, 1000);
        } else {
            if (gubun === "3") {
                $c.util.getComponent("movie1").setStyle("display", "none");
                $c.util.getComponent("movie2").setStyle("display", "none");
                self.setTimeout(function(){ scwin.playMovie('emb3') }, 1000);
            }
        }
    }
    console.error("[sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.playMovie
 * @author Inswave
 * @date 2026. 09. 29
 * @param oMyObj
 * @returns
 * @hidden N
*/
scwin.playMovie = function (oMyObj) {
    /* sdd-asis-lifecycle:begin playMovie — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const div_explan = $c.util.getComponent('movies');
    if (div_explan) {
        const explan_a = div_explan.getElementsByTagName('embed');
        for (let i = 0; i < explan_a.length; i++) {
            const ep_e = explan_a[i];
            if (ep_e.id === oMyObj) {
                ep_e.play();
            } else {
                ep_e.stop();
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};
